import type { BrokerMessage, BrokerEvent, PublishInput } from "./mqtt-types";
import type { WidgetJson } from "@homarr/widget-sdk/server";
import { defineWidgetServer } from "@homarr/widget-sdk/server";
import { brokerSettings, connectBroker } from "./mqtt-adapter";

export default defineWidgetServer({
  setup: async (_input,context) => {
    const {topics,publishTopics} = await brokerSettings(context);
    return {topics,publishTopics};
  },
  messages: async function* (_input,context):AsyncGenerator<BrokerEvent> {
    const configuration = await brokerSettings(context);
    const {client,close} = await connectBroker(context,configuration);
    const queue:BrokerMessage[] = [];
    let wake = () => {};
    let failure:Error|undefined;
    let dropped = 0;
    const onMessage = (topic:string,buffer:Buffer,packet:{retain:boolean}) => {
      const truncated = buffer.length > 65536;
      const text = buffer.subarray(0,65536).toString("utf8");
      let payload:WidgetJson = text;
      try { payload = JSON.parse(text); } catch {}
      if (queue.length >= 64) {queue.shift();dropped++;}
      queue.push({kind:"message",topic,payload,truncated,retained:packet.retain,dropped,receivedAt:new Date().toISOString()});
      wake();
    };
    const onError = (error:Error) => {failure=error;wake();};
    const onClose = () => {if (!context.signal.aborted) onError(new Error("Broker connection closed; reconnect to resume"));};
    const onAbort = () => wake();
    client.on("message",onMessage);client.on("error",onError);client.on("close",onClose);
    context.signal.addEventListener("abort",onAbort,{once:true});
    try {
      const grants = await client.subscribeAsync(configuration.topics,{qos:0});
      if (grants.some((grant) => grant.qos === 128)) throw new Error("The broker denied a configured topic subscription");
      yield {kind:"connected",topics:configuration.topics,receivedAt:new Date().toISOString()};
      while (!context.signal.aborted) {
        if (failure) throw failure;
        if (queue.length) {yield queue.shift()!;continue;}
        await new Promise<void>((resolve) => {wake=resolve;if (context.signal.aborted || failure || queue.length) resolve();});
      }
    } finally {
      context.signal.removeEventListener("abort",onAbort);
      client.off("message",onMessage);client.off("error",onError);client.off("close",onClose);
      await close();
    }
  },
  publish: async (input:PublishInput,context) => {
    const configuration = await brokerSettings(context);
    if (!configuration.publishTopics.includes(input?.topic)) throw new Error("Choose an owner-configured publish topic");
    if (typeof input.payload !== "string" || Buffer.byteLength(input.payload,"utf8") > 4096) throw new Error("The payload must be a string under 4 KiB");
    const {client,close} = await connectBroker(context,configuration);
    try {
      await client.publishAsync(input.topic,input.payload,{qos:1,retain:false});
      return {published:true,topic:input.topic};
    } finally { await close(); }
  },
});

