import type { WidgetJson } from "@homarr/widget-sdk/server";
export interface BrokerMessage {kind:"message";topic:string;payload:WidgetJson;truncated:boolean;retained:boolean;dropped:number;receivedAt:string}
export interface BrokerConnected {kind:"connected";topics:string[];receivedAt:string}
export type BrokerEvent = BrokerMessage | BrokerConnected;
export interface PublishInput {topic:string;payload:string}

