declare module "mqtt/lib/client" {
  import { EventEmitter } from "node:events";
  import type { Duplex } from "node:stream";
  interface Options {clientId:string;username?:string;password?:string;reconnectPeriod:number;connectTimeout:number;clean:boolean;manualConnect:boolean;log:(...values:unknown[])=>void}
  export default class MqttClient extends EventEmitter {
    constructor(streamBuilder:()=>Duplex,options:Options);
    connect():this;
    end(force?:boolean):this;
    endAsync(force?:boolean):Promise<void>;
    subscribeAsync(topics:string[],options:{qos:0|1|2}):Promise<{qos:0|1|2|128}[]>;
    publishAsync(topic:string,payload:string,options:{qos:0|1|2;retain:boolean}):Promise<void>;
  }
}

