import type { WidgetServerContext } from "@homarr/widget-sdk/server";
interface LocalMqttSettings {url?:string;topics?:unknown[];publishTopics?:unknown[];ca?:string;cert?:string;rejectUnauthorized?:boolean}
import MqttClient from "mqtt/lib/client";
import { createConnection, isIP } from "node:net";
import { connect as connectTls } from "node:tls";
import { randomUUID } from "node:crypto";
import { getWidgetConnection } from "@homarr/widget-sdk/server";

export async function brokerSettings(context:WidgetServerContext) {
  const {configuration,secrets} = await getWidgetConnection<LocalMqttSettings>(context,{connection:"broker",serviceType:"mqtt"});
  const settings = configuration.settings ?? {};
  if (typeof settings.url !== "string") throw new Error("Set the MQTT service url, for example mqtt://mosquitto:1883");
  const url = new URL(settings.url);
  if (!["mqtt:","mqtts:"].includes(url.protocol)) throw new Error("Choose an mqtt:// or mqtts:// broker URL");
  if (url.username || url.password) throw new Error("Put the broker username and password in encrypted credentials, not the URL");
  const topics = Array.isArray(settings.topics) ? settings.topics.filter((topic):topic is string => typeof topic === "string" && topic.length > 0).slice(0,32) : [];
  if (!topics.length) throw new Error("Set a nonempty topics array on the broker connection");
  const publishTopics = Array.isArray(settings.publishTopics) ? settings.publishTopics.filter((topic):topic is string => typeof topic === "string" && topic.length > 0 && !/[+#]/.test(topic)).slice(0,32) : [];
  return {settings:{...settings,url:settings.url},secrets,topics,publishTopics,timeoutMs:Math.min(configuration.timeoutMs,15000)};
}

export async function connectBroker(context:WidgetServerContext,configuration:Awaited<ReturnType<typeof brokerSettings>>) {
  context.signal.throwIfAborted();
  const {settings,secrets,timeoutMs} = configuration;
  const url = new URL(settings.url);
  const hostname = url.hostname.replace(/^\[|\]$/g, "");
  let port = url.protocol === "mqtts:" ? 8883 : 1883;
  if (url.port) port = Number(url.port);
  const stream = () => {
    if (url.protocol !== "mqtts:") return createConnection({host:hostname,port});
    return connectTls({host:hostname,port,servername:isIP(hostname) ? undefined : hostname,ca:settings.ca,cert:settings.cert,key:secrets.tlsKey,rejectUnauthorized:settings.rejectUnauthorized !== false});
  };
  const client = new MqttClient(stream,{
    clientId:`homarr-${randomUUID()}`,
    username:secrets.username || undefined,
    password:secrets.password || undefined,
    reconnectPeriod:0,
    connectTimeout:timeoutMs,
    clean:true,
    manualConnect:true,
    log:() => {},
  });
  const ignoreError = () => {};
  client.on("error",ignoreError);
  const stop = () => { client.end(true); };
  context.signal.addEventListener("abort",stop,{once:true});
  const close = async () => {
    context.signal.removeEventListener("abort",stop);
    await client.endAsync(true).catch(() => undefined);
    client.removeListener("error",ignoreError);
  };
  try {
    await new Promise<void>((resolve,reject) => {
      const cleanup = () => {client.off("connect",ready);client.off("error",failed);client.off("close",closed);};
      const ready = () => {cleanup();resolve();};
      const failed = (error:unknown) => {cleanup();reject(error);};
      const closed = () => failed(context.signal.reason ?? new Error("Broker connection closed before authentication completed"));
      client.once("connect",ready);client.once("error",failed);client.once("close",closed);
      if (context.signal.aborted) closed();
      else client.connect();
    });
    context.signal.throwIfAborted();
    return {client,close};
  } catch (error) { await close(); throw error; }
}

