import type server from "./server";
import type { BrokerEvent, BrokerMessage, PublishInput } from "./mqtt-types";
import { Alert, Badge, Button, Group, Select, Stack, Text, Textarea, TextInput } from "@mantine/core";
import { useWidgetAction, useWidgetCapabilities, useWidgetHost, useWidgetServices, useWidgetOptions, useWidgetQuery, useWidgetState, useWidgetSubscription } from "@homarr/widget-sdk";

export default function MqttWidget() {
  const host = useWidgetHost();
  const services = useWidgetServices();
  const options = useWidgetOptions<{title:string}>();
  const setup = useWidgetQuery<Awaited<ReturnType<typeof server.setup>>>("setup",{}, {staleTime:60000});
  const stream = useWidgetSubscription<BrokerEvent>("messages",{}, {maximumEvents:64});
  const publish = useWidgetAction<Awaited<ReturnType<typeof server.publish>>,PublishInput>("publish");
  const capabilities = useWidgetCapabilities();
  const [filter,setFilter] = useWidgetState("filter","");
  const [topic,setTopic] = useWidgetState("publishTopic","");
  const [payload,setPayload] = useWidgetState("payload","");
  const events = stream.events.filter((event):event is BrokerMessage => event.kind === "message" && event.topic.includes(filter)).slice().reverse();
  const latest = [...new Map(events.map((event) => [event.topic,event] as const).reverse()).values()].reverse();
  let visible = latest.slice(0,8);
  if (host.displayMode === "advanced") visible = events;
  const input = {topic,payload};
  const error = setup.error || stream.error || publish.error;
  return <Stack h="100%" p="sm" gap="xs">
    <Group justify="space-between"><Text fw={600}>{options.title}</Text><Badge color={stream.connected ? "green" : "gray"}>{stream.connected ? "Live" : "Disconnected"}</Badge></Group>
    {error && <Alert color="red">{error.message}<Button size="compact-xs" variant="subtle" onClick={() => stream.reconnect()}>Reconnect</Button></Alert>}
    <TextInput size="xs" aria-label="Filter MQTT topics" placeholder="Filter topics" value={filter} onChange={(event) => setFilter(event.currentTarget.value)} />
    <Stack gap="xs" style={{flex:1,minHeight:0,overflow:"auto"}}>
      {!visible.length && <Text size="sm" c="dimmed">Waiting for messages on {setup.data?.topics.join(", ") || "configured topics"}. Retained broker messages appear immediately.</Text>}
      {visible.map((event,index) => <Stack key={`${event.topic}:${event.receivedAt}:${index}`} gap={2} style={{borderBottom:"1px solid var(--mantine-color-default-border)",paddingBottom:6}}>
        <Group justify="space-between"><Text size="xs" fw={600}>{event.topic}</Text>{event.retained && <Badge size="xs" variant="light">Retained</Badge>}</Group>
        <Text component="pre" size="xs" style={{whiteSpace:"pre-wrap",margin:0}}>{typeof event.payload === "string" ? event.payload : JSON.stringify(event.payload,null,2)}</Text>
        <Text size="xs" c="dimmed">{new Date(event.receivedAt).toLocaleTimeString(host.locale)}{event.truncated ? " · payload truncated" : ""}{event.dropped ? ` · ${event.dropped} buffered messages dropped` : ""}</Text>
      </Stack>)}
    </Stack>
    {host.displayMode !== "advanced" && <Button size="compact-xs" variant="subtle" onClick={() => services.openAdvanced()}>Open message history</Button>}
    {host.displayMode === "advanced" && (setup.data?.publishTopics.length ?? 0) > 0 && <Stack gap="xs">
      <Select label="Publish topic" data={setup.data?.publishTopics ?? []} value={topic || null} onChange={(value) => setTopic(value || "")} />
      <Textarea label="Message payload" value={payload} onChange={(event) => setPayload(event.currentTarget.value)} maxLength={4096} />
      <Button disabled={!topic || !capabilities.canRun("publish",input)} loading={publish.isPending} onClick={async () => {if (await services.confirm({title:"Publish MQTT message",message:`Send this payload to ${topic}?`})) await publish.mutateAsync(input).catch(() => undefined);}}>Publish once (not retained)</Button>
      {publish.data?.published && <Text size="xs" c="green">Published to {publish.data.topic}</Text>}
    </Stack>}
  </Stack>;
}
